from pathlib import Path
from collections import defaultdict
from statistics import median
import json,re,sys
source=Path(sys.argv[1]);data=json.loads(source.read_text())
groups=defaultdict(lambda:defaultdict(list))
counts=defaultdict(lambda:defaultdict(list))
for run in data['runs']:
 for line in run['results']:
  if line.startswith('MARKSTREAM_RENDER '):
   record=json.loads(line.split(' ',1)[1]);scenario='fixed'
   metrics={k:v for k,v in record.items() if k.endswith('Us') and isinstance(v,(int,float))}
   for name in ['coldPhaseUs','contentPhaseMedianUs','contentPhaseP95Us']:
    for k,v in (record.get(name) or {}).items():metrics[f'{name}.{k}']=v
  else:
   record=dict(re.findall(r'(\w+)=([^\s]+)',line))
   if line.startswith('RESULT '):
    scenario='tools='+record['tools'];metrics={k:float(v) for k,v in record.items() if k.endswith('Ms')}
    for key in ['elements','renders','estExtent','measuredExtent','extentCorrections']:
     counts[(run['backdrop'],run['bench'],scenario,key)][run['revision']].append(float(record[key]))
   else:
    scenario=f'{record["paragraphs"]}-{record["shape"]}';metrics={k:float(v) for k,v in record.items() if k.endswith('Us')}
    stages=json.loads(re.search(r'stages=(\[[^\]]+\])',line).group(1))
    metrics.update(zip(['schedulingUs','contentUs','scrollUs'],stages))
  for name,value in metrics.items():groups[(run['backdrop'],run['bench'],scenario,name)][run['revision']].append(value)
rows=[]
for key,versions in groups.items():
 if len(versions['baseline'])!=5 or len(versions['current'])!=5:continue
 before=median(versions['baseline']);after=median(versions['current'])
 rows.append(dict(zip(['backdrop','bench','scenario','metric'],key),baseline=before,current=after,deltaPct=100*(after/before-1) if before else 0,rounds=versions))
result={'rows':rows,'geometry':[dict(zip(['backdrop','bench','scenario','metric'],key),values=value) for key,value in counts.items()]}
source.with_name('summary.json').write_text(json.dumps(result,indent=2))
for group in ['plain','wallpaper']:
 print('\n'+group)
 for row in rows:
  if row['backdrop']==group:
   print(f'{row["bench"]} {row["scenario"]} {row["metric"]}: {row["baseline"]:.2f} -> {row["current"]:.2f} ({row["deltaPct"]:+.2f}%)')
